package fr.roy.parlanime;
import android.content.*;import android.graphics.*;import java.io.*;import java.util.*;import java.util.zip.*;
public final class Packs {
 public static class Pack {public String id,name;public File folder;public Bitmap[][] images=new Bitmap[3][9];public Bitmap[][] states;public boolean custom;public Bitmap[] idle=new Bitmap[9];}
 public static ArrayList<Pack> list(Context c)throws Exception{ArrayList<Pack> a=new ArrayList<>();for(String id:c.getAssets().list("packs")){Pack p=new Pack();p.id=id;try(InputStream in=c.getAssets().open("packs/"+id+"/name.txt")){byte[] b=new byte[200];int n=in.read(b);p.name=new String(b,0,n,"UTF-8").trim();}a.add(p);}File dir=new File(c.getFilesDir(),"characters");File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isDirectory()){Pack p=new Pack();p.id=f.getName();p.name=f.getName();p.folder=f;p.custom=true;a.add(p);}return a;}
 public static void load(Context c,Pack p)throws Exception{if(p.custom){p.states=new Bitmap[4][9];for(int i=0;i<4;i++)for(int j=0;j<9;j++){p.states[i][j]=BitmapFactory.decodeFile(new File(p.folder,i+"-"+j+".png").getPath());if(p.states[i][j]==null)throw new IOException("Image invalide : "+i+".png");}}else {for(int i=0;i<9;i++)try(InputStream in=c.getAssets().open("packs/"+p.id+"/idle-"+i+".png")){p.idle[i]=BitmapFactory.decodeStream(in);if(p.idle[i]==null)throw new IOException("Animation d’attente invalide.");}for(int b=0;b<3;b++)for(int i=0;i<9;i++)try(InputStream in=c.getAssets().open("packs/"+p.id+"/"+b+"-"+i+".png")){p.images[b][i]=BitmapFactory.decodeStream(in);if(p.images[b][i]==null)throw new IOException("Pack invalide");}}}
 public static int idlePose(int tick){int t=Math.floorMod(tick,600);if(t<95)return 0;if(t<100)return 1;if(t<105)return 2;if(t<110)return 1;if(t<210)return 3;if(t<255)return 4;if(t<310)return 0;if(t<355)return 5;if(t<410)return 0;if(t<450)return 6;if(t<495)return 0;if(t<535)return 7;if(t<570)return 0;return 8;}
 public static Bitmap pose(Pack p,Voice.Frame f,Voice.Settings s){if(f.velocity==0)return p.custom?p.states[0][idlePose(f.tick)]:p.idle[idlePose(f.tick)];return p.custom?p.states[f.bank(s)+1][f.shape]:p.images[f.bank(s)][Math.max(0,Math.min(8,f.shape))];}
 public static Bitmap render(Pack p,Voice.Frame f,Voice.Settings s,int size,boolean transparent){return render(p,f,s,size,transparent,new Backdrop());}
 public static Bitmap render(Pack p,Voice.Frame f,Voice.Settings s,int size,boolean transparent,Backdrop background){Bitmap out=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);if(!transparent)background.draw(c,size,size);Bitmap im=pose(p,f,s);if(im!=null){float scale=Math.min(size/(float)im.getWidth(),size/(float)im.getHeight());float w=im.getWidth()*scale,h=im.getHeight()*scale;c.drawBitmap(im,null,new RectF((size-w)/2,(size-h)/2,(size+w)/2,(size+h)/2),new Paint(3));}return out;}
 public static Pack importSheet(Context c,InputStream in,String name)throws Exception{
  byte[] data=readLimited(in,32*1024*1024);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,bounds);if(bounds.outWidth<9||bounds.outHeight<4||bounds.outWidth%9!=0||bounds.outHeight%4!=0||bounds.outWidth/9!=bounds.outHeight/4||bounds.outWidth>4608)throw new IOException("Choisis une planche PNG de 9 colonnes × 4 rangées carrées, maximum 4608 × 2048.");
  Bitmap sheet=BitmapFactory.decodeByteArray(data,0,data.length);if(sheet==null)throw new IOException("Image illisible.");String clean=name.trim().replaceAll("[^\\p{L}\\p{N} _-]","");if(clean.isEmpty())clean="Mon personnage";File dir=new File(c.getFilesDir(),"characters/"+clean+"-"+System.currentTimeMillis());if(!dir.mkdirs())throw new IOException("Création du personnage impossible.");
  try{int cell=sheet.getWidth()/9;for(int i=0;i<4;i++)for(int j=0;j<9;j++){Bitmap crop=Bitmap.createBitmap(sheet,j*cell,i*cell,cell,cell);Bitmap scaled=Bitmap.createScaledBitmap(crop,256,256,true);try(FileOutputStream out=new FileOutputStream(new File(dir,i+"-"+j+".png"))){scaled.compress(Bitmap.CompressFormat.PNG,100,out);}if(scaled!=crop)scaled.recycle();crop.recycle();}}finally{sheet.recycle();}  Pack p=new Pack();p.id=dir.getName();p.name=clean;p.folder=dir;p.custom=true;load(c,p);return p;
 }
 static byte[] readLimited(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Image trop volumineuse (32 Mo maximum).");out.write(b,0,n);}return out.toByteArray();}
}
